  var currentLang = settings.language || "en";

  function t(key) { return (i18n[currentLang] && i18n[currentLang][key]) || (i18n.en[key]) || key; }

  function applyI18n() {
    $$("[data-i18n]").forEach(function(el) {
      var key = el.getAttribute("data-i18n");
      var val = t(key);
      if (val) el.textContent = val;
    });
    $$("[data-i18n-placeholder]").forEach(function(el) {
      var key = el.getAttribute("data-i18n-placeholder");
      var val = t(key);
      if (val) el.placeholder = val;
    });
  }

  $("#set-language").addEventListener("change",function(){
    currentLang=this.value;
    settings.language=currentLang;
    window.api.saveSettings(settings);
    applyI18n();
    if(typeof refreshModelsTab==="function")refreshModelsTab();
  });

  // Wizard language dropdown — same behavior
  $("#wiz-language").addEventListener("change",function(){
    currentLang=this.value;
    settings.language=currentLang;
    window.api.saveSettings(settings);
    applyI18n();
  });

  var modelNames = {"ggml-base.bin":"Base","ggml-base.en.bin":"Base.en","ggml-small.bin":"Small","ggml-small.en.bin":"Small.en","ggml-medium.bin":"Medium","ggml-medium.en.bin":"Medium.en","ggml-large-v3.bin":"Large V3","ggml-large-v2.bin":"Large V2","ggml-large-v3-turbo.bin":"Large V3 Turbo","ggml-tiny.bin":"Tiny","ggml-tiny.en.bin":"Tiny.en"};
  function friendlyModelName(filename) { return modelNames[filename] || filename.replace("ggml-","").replace(".bin",""); }

